// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 strike, uint256 premium, uint256 nonce, uint256 duration) public {
        // keep parameters in the admissible domain (wide)
        duration = bound(duration, 0, 10_000 days - 1);

        // permissive ERC20 so the premium/strike safeTransferFrom low-level calls succeed
        Token token = new Token();
        // adversarial maker: an ERC1271 contract whose signature is always valid
        ERC1271Maker maker = new ERC1271Maker();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = hex"";
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        // first fill succeeds on both versions
        bool ok1;
        try c.fillOrder(order, sig, floorAssetTokenIds) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        assertTrue(ok1, "first fill must succeed");

        // GENERAL RULE: any order can be filled at most once - a second fill of the
        // exact same order must revert because the maker position was already minted.
        bool ok2;
        try c.fillOrder(order, sig, floorAssetTokenIds) {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        assertTrue(!ok2, "same order must not be fillable twice");
    }
}

contract ERC1271Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract Token {
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
}
